// Bağlantı satırına basışın türü. Saf mantık: React içermez; test doğrudan bunu okur.

/** Basışın alanları; React ve DOM fare olayları ikisi de uyar. */
export interface ClickLike { button: number; metaKey: boolean; ctrlKey: boolean; shiftKey: boolean; altKey: boolean; defaultPrevented: boolean }

/**
 * Sayfa içinde gidilecek düz basış mı? Sol tuş, değiştirici tuş yok, önlenmemiş. Ctrl/⌘ (yeni sekme), Shift (yeni pencere),
 * Alt (indir) ve orta tuş tarayıcıya bırakılır; uygulama yönlendirmesi yalnız düz basışta yapılır.
 */
export function isPlainClick(event: ClickLike): boolean {
  return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey && !event.defaultPrevented;
}

/* Uygulama çerçevesi: çerçeve sabit boyda durur, kayma içerik alanının içinde olur. Çekmece bu kökün içinde çizilir (position: relative; overflow: hidden). */
.root { --sidebar-icon: 1.25rem; position: relative; display: flex; height: 100%; min-height: 20rem; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-panel); color: var(--foreground); background: var(--background); font-family: var(--font-body); }
/* Çerçevesiz: yalnız yan menü; kenarlık ve köşe uygulamanın kabuğundadır. Yükseklik kapsayıcıdan gelir. Geçici açılan menü içeriğin
   üstüne taşabilsin diye kırpmaz (çekmece sayfa gövdesine açılır, kökü kırpmaya gerek yok). */
.root[data-frameless] { min-height: 0; overflow: visible; border: 0; border-radius: 0; background: transparent; }
.status, .srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
/* Satır yüksekliği ve köşesi değişkenle: sık kabukta --sidebar-row-height: 36px, hap biçimi için --sidebar-row-radius: 999px. */
.asideSlot { position: relative; z-index: 2; flex: none; }
.aside { position: absolute; inset: 0 auto 0 0; overflow: hidden; border-right: 1px solid var(--border); background: var(--surface-muted); }
.aside[data-peek="true"] { box-shadow: var(--shadow-floating); }
.drawer { padding: 0; }
.panel { display: flex; width: 100%; min-width: 3.5rem; height: 100%; flex-direction: column; overflow: hidden; }
.aside .panel { width: 16rem; }
.aside .panel[data-rail="true"] { width: 3.5rem; }
.brand { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-4) var(--space-3); }
.logo { display: grid; width: 2rem; height: 2rem; flex: none; place-items: center; border-radius: var(--radius-control); color: var(--accent-foreground); background: var(--accent); font-size: var(--text-sm); font-weight: 600; }
.brandCopy, .userCopy { display: grid; min-width: 0; transition: opacity var(--duration-fast) var(--ease-standard); }
.brandName, .brandSub, .userName, .userSub { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.brandName, .userName { font-size: var(--text-sm); font-weight: 600; }
.brandSub, .userSub { color: var(--text-muted); font-size: var(--text-xs); }
.nav { display: grid; min-height: 0; flex: 1; align-content: start; gap: var(--space-4); overflow: auto; padding: var(--space-2); }
.section { display: grid; gap: var(--space-1); }
/* İki sınıflı seçici: projenin genel h2 kuralı (yazı tipi, boy) grup başlığını ezmesin. */
.nav .sectionTitle { margin: 0; padding: 0 var(--space-3); color: var(--text-muted); font-family: inherit; font-size: var(--text-xs); font-weight: 500; letter-spacing: inherit; line-height: var(--leading-body); }
.list, .children { display: grid; gap: var(--space-1); margin: 0; padding: 0; list-style: none; }
.children { margin-left: var(--space-5); border-left: 1px solid var(--border); padding-left: var(--space-2); overflow: hidden; }
.row { position: relative; display: flex; width: 100%; min-height: var(--sidebar-row-height, var(--control-height-md)); align-items: center; gap: var(--space-3); border: 0; border-radius: var(--sidebar-row-radius, var(--radius-control)); padding: 0 var(--space-3); color: var(--text-secondary); background: transparent; font: inherit; font-size: var(--text-sm); text-align: left; text-decoration: none; cursor: pointer; transition: background var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.row[data-active="true"] { color: var(--foreground); background: var(--accent-subtle); font-weight: 500; }
.row:focus-visible, .user:focus-visible, .flyoutRow:focus-visible { outline: var(--focus-outline-width) solid var(--focus-outline); outline-offset: var(--focus-outline-offset); }
@media (hover: hover) and (pointer: fine) { .row:hover, .user:hover:not(:disabled), .flyoutRow:hover { color: var(--foreground); background: var(--surface-raised); } .row[data-active="true"]:hover { background: var(--accent-subtle); } }
.row[data-disabled] { color: var(--text-muted); cursor: not-allowed; }
@media (hover: hover) and (pointer: fine) { .row[data-disabled]:hover { color: var(--text-muted); background: transparent; } }
.note { flex: none; color: var(--text-muted); font-size: var(--text-xs); transition: opacity var(--duration-fast) var(--ease-standard); }
.pin { flex: none; margin-left: auto; }
.icon { display: grid; width: var(--sidebar-icon); height: var(--sidebar-icon); flex: none; place-items: center; }
.label { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: opacity var(--duration-fast) var(--ease-standard); }
.chevron { flex: none; transition: transform var(--duration-standard) var(--ease-standard); }
.chevron[data-open="true"] { transform: rotate(180deg); }
/* Şeritte yazılar önce solar, sonra genişlik daralır (genişliği çerçeve yayla izler). */
.panel[data-rail="true"] .label, .panel[data-rail="true"] .note, .panel[data-rail="true"] .brandCopy, .panel[data-rail="true"] .userCopy { opacity: 0; }
.panel[data-rail="true"] .sectionTitle { display: none; }
/* Şeritte satır simgeyi ortalar; yazının boşluğu şeride taşıp seçili satırı kenarda kesmesin. */
.panel[data-rail="true"] .row { justify-content: center; gap: 0; padding: 0; }
.panel[data-rail="true"] .label { flex: 0 0 0; }
.foot { display: grid; gap: var(--space-1); border-top: 1px solid var(--border); padding: var(--space-2); }
.user { display: flex; width: 100%; align-items: center; gap: var(--space-3); border: 0; border-radius: var(--radius-control); padding: var(--space-2) var(--space-3); color: inherit; background: transparent; font: inherit; text-align: left; cursor: pointer; }
.user:disabled { cursor: default; }
.flyout { display: grid; min-width: 11rem; gap: var(--space-1); padding: var(--space-2); }
.flyoutTitle { padding: var(--space-1) var(--space-3); color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; }
.flyoutRow { display: flex; width: 100%; min-height: var(--control-height-sm); align-items: center; border: 0; border-radius: var(--radius-control); padding: 0 var(--space-3); color: var(--text-secondary); background: transparent; font: inherit; font-size: var(--text-sm); text-align: left; cursor: pointer; }
.flyoutRow[aria-current="page"] { color: var(--foreground); background: var(--accent-subtle); }
.error { display: grid; gap: var(--space-2); justify-items: start; border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--space-3); color: var(--text-secondary); font-size: var(--text-sm); }
.loading { padding: var(--space-3); }
.main { display: flex; min-width: 0; flex: 1; flex-direction: column; }
.topbar { display: flex; min-height: 3rem; align-items: center; gap: var(--space-3); border-bottom: 1px solid var(--border); padding: 0 var(--space-3); }
.content { min-height: 0; flex: 1; overflow: auto; padding: var(--space-5); }
@media (prefers-reduced-motion: reduce) { .row, .label, .brandCopy, .userCopy, .chevron { transition: none; } }

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import type { KeyboardEvent as ReactKeyboardEvent, MouseEvent as ReactMouseEvent, ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { Transition } from "motion/react";
import { ChevronDown, Menu, PanelLeft, Pin, PinOff } from "lucide-react";
import { text } from "@snn/abacus-core";
import { motionTokens } from "../lib/motion-tokens";
import { Avatar } from "../avatar/avatar";
import { Badge } from "../badge/badge";
import { Breadcrumb } from "../breadcrumb/breadcrumb";
import { Button } from "../button/button";
import { Drawer, DrawerContent } from "../drawer/drawer";
import { Popover, PopoverClose, PopoverContent, PopoverTrigger } from "../popover/popover";
import { Skeleton } from "../skeleton/skeleton";
import { Tooltip } from "../tooltip/tooltip";
import { isPlainClick } from "./sidebar-click";
import styles from "./sidebar.module.css";

export interface SidebarItem {
  id: string;
  label: string;
  /** Satırın solundaki simge. Süstür; şeritte (daralmış menü) tek görünen şey budur, adı ipucunda çıkar. */
  icon?: ReactNode | undefined;
  /** Okunmamış gibi bir sayı. Ekran okuyucu "{n} okunmamış" okur. */
  badge?: number | undefined;
  /** Verilirse satır düz bağlantı (`<a>`) olarak çizilir; verilmezse düğme. Her iki durumda `onNavigate` çağrılır. Bağlantıda
   * Ctrl/⌘, Shift, Alt ya da orta tuşla basış tarayıcıya bırakılır (yeni sekme); `onNavigate` çağrılmaz. */
  href?: string | undefined;
  /** Alt satırlar: satır katlanır gruba döner. Boş dizi verilirse grup hiç gösterilmez. */
  children?: SidebarItem[] | undefined;
  /** Pasif satır: görünür ve odaklanır ama gitmez; ekran okuyucu "kullanılamaz" okur. */
  disabled?: boolean | undefined;
  /** Satırın sağındaki kısa not, ör. "Yakında". Şeritte ipucuna eklenir. */
  note?: string | undefined;
}

export interface SidebarSection { id: string; title?: string | undefined; items: SidebarItem[] }

export interface SidebarMenuAction { id: string; label: string; onSelect: () => void }

export interface SidebarUser { name: string; subtitle?: string | undefined; src?: string | undefined; /** Kart açılınca listelenen eylemler (profil, çıkış yap gibi). */ menu?: SidebarMenuAction[] | undefined }

export interface SidebarProps {
  header: { name: string; subtitle?: string | undefined; logo?: ReactNode | undefined };
  sections: SidebarSection[];
  /** Etkin sayfanın `id`'si. Bulunamazsa hiçbir satır vurgulanmaz, yol izi yalnız ana bölümü gösterir. */
  activeId?: string | undefined;
  /** Satıra basınca. Bağlantı satırında `event` de gelir: istemci yönlendirmesi için `event.preventDefault()` deyip kendi router'ınızla
   * gidin (tam sayfa yenilenmez, `<a href>` kalır; sağ tık "yeni sekmede aç" çalışır). */
  onNavigate: (id: string, event?: ReactMouseEvent<HTMLAnchorElement>) => void;
  /** Alt alandaki Ayarlar satırı. */
  settingsItem?: SidebarItem | undefined;
  user?: SidebarUser | undefined;
  collapsed?: boolean | undefined;
  defaultCollapsed?: boolean | undefined;
  /** Katlama tercihini uygulama saklar; blok yalnız haber verir. */
  onCollapsedChange?: ((collapsed: boolean) => void) | undefined;
  /** Menü verisi geliyorsa true: satırlar yerine iskelet çıkar. */
  loading?: boolean | undefined;
  /** Menü verisi alınamadıysa true: kısa mesaj ve "Yeniden dene" çıkar; `sections` içinde gömülü yedek menü verilebilir. */
  error?: boolean | undefined;
  onRetry?: (() => void) | undefined;
  /** Bu genişliğin (px) altında menü çekmeceye dönüşür. Ölçü pencereye değil bloğun kendi genişliğine bakar. */
  breakpoint?: number | undefined;
  /** Şeritteyken üzerine gelince ya da klavye odağı girince menü içeriğin üstüne geçici genişler; raptiye düğmesi açık bırakır
   * (`onCollapsedChange(false)`), raptiyeyi kaldırmak yeniden şeride döndürür. */
  hoverExpand?: boolean | undefined;
  /** Geçici açılan menüyü açık tutar; içerideki açılır pencere (kullanıcı menüsü, bildirim merkezi) açıkken true verin, yoksa
   * pencere menünün dışına çizildiği için imleç ya da odak ona geçince menü daralır. false olunca imleç ve odak dışarıdaysa daralır. */
  holdExpanded?: boolean | undefined;
  /** Alt alanda Ayarlar ve kullanıcı kartından sonra gelen serbest içerik (bildirim merkezi, kendi kullanıcı menünüz). İşlev verilirse
   * şeritte olup olmadığını alır; şeritte yalnız simge göstermek için. */
  footer?: ReactNode | ((state: { rail: boolean }) => ReactNode) | undefined;
  /** Çerçevesiz: yalnız yan menü çizilir; üst çubuk, yol izi ve içerik alanı yoktur (`children` kullanılmaz). Çekmece kararı pencere
   * genişliğine bakar; dar ekranda menü gizlenir ve çekmeceyi uygulamanın kendi üst çubuğu `drawerOpen` / `onDrawerOpenChange` ile açar. */
  frameless?: boolean | undefined;
  /** Dar ekrandaki çekmecenin açıklığı (denetimli). Çerçevesiz kipte açma düğmesi uygulamadadır. */
  drawerOpen?: boolean | undefined;
  onDrawerOpenChange?: ((open: boolean) => void) | undefined;
  /** Sayfa içeriği; kendi içinde kayar, çerçeve sabit kalır. */
  children?: ReactNode | undefined;
  className?: string | undefined;
}

interface Found { item: SidebarItem; trail: SidebarItem[]; section: SidebarSection }

function findItem(sections: SidebarSection[], id: string | undefined): Found | null {
  if (!id) return null;
  for (const section of sections) {
    const walk = (items: SidebarItem[], trail: SidebarItem[]): Found | null => {
      for (const item of items) {
        if (item.id === id) return { item, trail, section };
        const inner = item.children ? walk(item.children, [...trail, item]) : null;
        if (inner) return inner;
      }
      return null;
    };
    const hit = walk(section.items, []);
    if (hit) return hit;
  }
  return null;
}

/** Çocuğu olmayan boş grup (`children: []`) gösterilmez. */
const visible = (items: SidebarItem[]) => items.filter(item => !(item.children && item.children.length === 0));
const badgeText = (count: number) => `${count} okunmamış`;

/** Solda daralabilen menü, üstte yol izi, ortada kayan içerik olan uygulama çerçevesi. Dar kolonda menü çekmeceye dönüşür. */
export function Sidebar({
  header, sections, activeId, onNavigate, settingsItem, user, collapsed: collapsedProp, defaultCollapsed = false, onCollapsedChange,
  loading = false, error = false, onRetry, breakpoint = 720, hoverExpand = false, holdExpanded = false, footer, frameless = false, drawerOpen: drawerOpenProp, onDrawerOpenChange,
  children, className,
}: SidebarProps) {
  const uid = useId();
  const reduced = useReducedMotion();
  const [root, setRoot] = useState<HTMLDivElement | null>(null);
  const [narrow, setNarrow] = useState(false);
  const [drawerState, setDrawerState] = useState(false);
  const drawerOpen = drawerOpenProp ?? drawerState;
  const setDrawerOpen = useCallback((next: boolean) => {
    if (drawerOpenProp === undefined) setDrawerState(next);
    if (next !== drawerOpen) onDrawerOpenChange?.(next);
  }, [drawerOpenProp, drawerOpen, onDrawerOpenChange]);
  const [collapsedState, setCollapsedState] = useState(defaultCollapsed);
  const collapsed = collapsedProp ?? collapsedState;
  /** Şerit üzerine gelince ya da odakla geçici açık. */
  const [peek, setPeek] = useState(false);
  const peekTimer = useRef<number | undefined>(undefined);
  /** İmleç ya da odak menünün içinde mi; tutma bırakılınca daralıp daralmayacağına bakılır. */
  const inside = useRef({ pointer: false, focus: false });
  useEffect(() => () => window.clearTimeout(peekTimer.current), []);
  useEffect(() => { if (!collapsed || !hoverExpand) setPeek(false); }, [collapsed, hoverExpand]);
  // Kısa bekleme: imleç şeridin üstünden geçip giderken menü açılıp kapanmaz. Tutulurken daralmaz.
  const schedulePeek = (next: boolean) => {
    window.clearTimeout(peekTimer.current);
    if (!hoverExpand || !collapsed || (!next && holdExpanded)) return;
    peekTimer.current = window.setTimeout(() => setPeek(next), next ? 120 : 200);
  };
  const latestPeek = useRef(schedulePeek);
  latestPeek.current = schedulePeek;
  useEffect(() => {
    if (!holdExpanded && !inside.current.pointer && !inside.current.focus) latestPeek.current(false);
  }, [holdExpanded]);
  const found: Found | null = findItem(sections, activeId) ?? (settingsItem && activeId && settingsItem.id === activeId ? { item: settingsItem, trail: [], section: { id: "", items: [] } } : null);
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>(() => {
    const initial: Record<string, boolean> = {};
    for (const trail of findItem(sections, activeId)?.trail ?? []) initial[trail.id] = true;
    return initial;
  });
  const [note, setNote] = useState("");
  const firstRun = useRef(true);

  // Bloğun kendi genişliğini izler: çekmece kararı pencereye değil, bulunduğu kolona göre verilir. Çerçevesiz kipte blok menünün
  // kendisidir (her zaman dar), bu yüzden pencereye bakılır.
  useEffect(() => {
    if (!frameless) return;
    const media = window.matchMedia(`(max-width: ${breakpoint - .02}px)`);
    const onChange = () => setNarrow(media.matches);
    onChange();
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, [frameless, breakpoint]);
  useEffect(() => {
    if (!root || frameless) return;
    const observer = new ResizeObserver(([entry]) => { if (entry) setNarrow(entry.contentRect.width < breakpoint); });
    observer.observe(root);
    return () => observer.disconnect();
  }, [root, breakpoint, frameless]);
  // İlk çizimde ve her yeniden çizimde de ölçülür: gözlemci gelene kadar menü yanlış kipte yanıp sönmez.
  useLayoutEffect(() => { if (root && !frameless) setNarrow(root.clientWidth < breakpoint); }, [root, frameless, breakpoint]);
  // Geniş kipte çekmece olmaz; açık kalmışsa kapanır.
  useEffect(() => { if (!narrow && drawerOpen) setDrawerOpen(false); }, [narrow, drawerOpen, setDrawerOpen]);

  // Sayfa değişince ekran okuyucuya haber verilir (ilk çizimde değil).
  const foundLabel = found?.item.label;
  useEffect(() => {
    if (firstRun.current) { firstRun.current = false; return; }
    if (foundLabel) setNote(`${foundLabel} bölümü açıldı`);
  }, [activeId, foundLabel]);

  const setCollapsed = useCallback((next: boolean) => {
    if (collapsedProp === undefined) setCollapsedState(next);
    onCollapsedChange?.(next);
  }, [collapsedProp, onCollapsedChange]);

  // Ctrl+B menüyü katlar/açar; yazı alanında, menüde ya da pencerede odak varsa çalışmaz.
  const latest = useRef({ collapsed, narrow, setCollapsed });
  latest.current = { collapsed, narrow, setCollapsed };
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.code !== "KeyB" || !(event.ctrlKey || event.metaKey) || event.altKey || event.shiftKey || latest.current.narrow) return;
      const target = event.target instanceof Element ? event.target : null;
      if (target?.closest("input, textarea, select, [contenteditable='true'], [role='dialog'], [role='menu'], [role='listbox']")) return;
      event.preventDefault();
      latest.current.setCollapsed(!latest.current.collapsed);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const toggleGroup = (id: string) => setOpenGroups(current => ({ ...current, [id]: !current[id] }));

  function go(item: SidebarItem, event?: ReactMouseEvent<HTMLAnchorElement>) {
    if (item.disabled) return;
    // Yeni sekme/pencere basışı tarayıcıya kalır; menü de olduğu gibi kalır.
    if (event && !isPlainClick(event)) return;
    onNavigate(item.id, event);
    setDrawerOpen(false);
  }

  // Yukarı/aşağı ok satırlar arasında gezer; sağ ok grubu açar, sol ok kapatır. Tab ile de sırayla gezilir.
  function onNavKeyDown(event: ReactKeyboardEvent<HTMLElement>) {
    const target = event.target instanceof HTMLElement ? event.target : null;
    if (!target) return;
    if ((event.key === "ArrowRight" || event.key === "ArrowLeft") && target.dataset.groupId) {
      const open = target.getAttribute("aria-expanded") === "true";
      if ((event.key === "ArrowRight") !== open) { event.preventDefault(); toggleGroup(target.dataset.groupId); }
      return;
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    const all = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("[data-nav-item]")).filter(node => node.offsetParent !== null);
    const index = all.indexOf(target);
    if (index < 0) return;
    event.preventDefault();
    all[(index + (event.key === "ArrowDown" ? 1 : -1) + all.length) % all.length]?.focus();
  }

  const grow: Transition = reduced ? { duration: 0 } : motionTokens.spring.smooth;

  function renderRow(item: SidebarItem, rail: boolean): ReactNode {
    const active = item.id === activeId;
    const hasChildren = !!item.children && item.children.length > 0;
    const open = !!openGroups[item.id];
    const contains = hasChildren && !!findItem([{ id: "", items: item.children! }], activeId);
    const content = (
      <>
        {item.icon ? <span className={styles.icon} aria-hidden="true">{item.icon}</span> : <span className={styles.icon} aria-hidden="true" />}
        <span className={styles.label}>{item.label}</span>
        {typeof item.badge === "number" && item.badge > 0 && !rail && <><Badge size="sm" tone="info" aria-hidden="true">{String(item.badge)}</Badge><span className={styles.srOnly}>{badgeText(item.badge)}</span></>}
        {item.note && !rail && <span className={styles.note}>{item.note}</span>}
        {hasChildren && !rail && <ChevronDown className={styles.chevron} data-open={open ? "true" : undefined} size={16} aria-hidden="true" />}
      </>
    );
    const tip = typeof item.badge === "number" && item.badge > 0 ? `${item.label} (${badgeText(item.badge)})` : item.note ? `${item.label} (${item.note})` : item.label;
    const off = item.disabled || undefined;

    if (hasChildren && rail) {
      // Şeritteyken grup simgesi menüyü açmaz; alt sayfalar küçük bir açılır kutuda listelenir.
      return (
        <li key={item.id}>
          <Popover>
            <Tooltip content={item.label} side="right">
              <PopoverTrigger asChild>
                <button type="button" className={styles.row} data-nav-item data-active={contains ? "true" : undefined} aria-label={item.label}>{content}</button>
              </PopoverTrigger>
            </Tooltip>
            <PopoverContent side="right" align="start" className={styles.flyout}>
              <span className={styles.flyoutTitle}>{item.label}</span>
              {item.children!.map(child => (
                <PopoverClose asChild key={child.id}>
                  <button type="button" className={styles.flyoutRow} aria-current={child.id === activeId ? "page" : undefined} onClick={() => go(child)}>{child.label}</button>
                </PopoverClose>
              ))}
            </PopoverContent>
          </Popover>
        </li>
      );
    }

    if (hasChildren) {
      return (
        <li key={item.id}>
          <button type="button" className={styles.row} data-nav-item data-group-id={item.id} data-active={contains && !open ? "true" : undefined} aria-expanded={open} aria-controls={`${uid}-${item.id}`} onClick={() => toggleGroup(item.id)}>{content}</button>
          <AnimatePresence initial={false}>
            {open && (
              <motion.ul
                key="children" id={`${uid}-${item.id}`} className={styles.children}
                initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={grow}
              >
                {visible(item.children!).map(child => renderRow(child, false))}
              </motion.ul>
            )}
          </AnimatePresence>
        </li>
      );
    }

    // Pasif satır bağlantı olmaz; aria-disabled odaklanabilir bırakır, böylece "Yakında" klavyeyle de okunur.
    const row = item.href && !off
      ? <a href={item.href} className={styles.row} data-nav-item data-active={active ? "true" : undefined} aria-current={active ? "page" : undefined} aria-label={rail ? tip : undefined} onClick={event => go(item, event)}>{content}</a>
      : <button type="button" className={styles.row} data-nav-item data-active={active && !off ? "true" : undefined} data-disabled={off} aria-disabled={off} aria-current={active && !off ? "page" : undefined} aria-label={rail ? tip : undefined} onClick={() => go(item)}>{content}</button>;
    return <li key={item.id}>{rail ? <Tooltip content={tip} side="right">{row}</Tooltip> : row}</li>;
  }

  function userTrigger(user: SidebarUser) {
    return (
      <PopoverTrigger asChild>
        <button type="button" className={styles.user} aria-label={`${user.name}, hesap menüsü`} disabled={!user.menu?.length}>
          <Avatar name={user.name} src={user.src} size="sm" />
          <span className={styles.userCopy}><span className={styles.userName}>{user.name}</span>{user.subtitle && <span className={styles.userSub}>{user.subtitle}</span>}</span>
        </button>
      </PopoverTrigger>
    );
  }

  function renderNav(rail: boolean) {
    return (
      <div className={styles.panel} data-rail={rail ? "true" : undefined}>
        <div className={styles.brand}>
          <span className={styles.logo} aria-hidden="true">{header.logo ?? text.upper(header.name.trim().charAt(0))}</span>
          <span className={styles.brandCopy}><span className={styles.brandName}>{header.name}</span>{header.subtitle && <span className={styles.brandSub}>{header.subtitle}</span>}</span>
          {hoverExpand && !rail && !narrow && (
            <Tooltip content={collapsed ? "Menüyü açık tut" : "Menüyü şeride döndür"}>
              <Button variant="ghost" size="sm" className={styles.pin} aria-label="Menüyü açık tut" aria-pressed={!collapsed} onClick={() => setCollapsed(!collapsed)}>
                {collapsed ? <Pin size={16} aria-hidden="true" /> : <PinOff size={16} aria-hidden="true" />}
              </Button>
            </Tooltip>
          )}
        </div>
        <nav className={styles.nav} aria-label="Ana menü" onKeyDown={onNavKeyDown}>
          {error && (
            <div className={styles.error} role="alert">
              <span>Menü yüklenemedi.</span>
              {onRetry && <Button variant="secondary" size="sm" onClick={onRetry}>Yeniden dene</Button>}
            </div>
          )}
          {loading ? <div className={styles.loading}><Skeleton label="Menü yükleniyor" lines={5} /></div> : sections.map(section => {
            const items = visible(section.items);
            if (items.length === 0) return null;
            return (
              <section key={section.id} className={styles.section} aria-label={section.title}>
                {section.title && !rail && <h2 className={styles.sectionTitle}>{section.title}</h2>}
                <ul className={styles.list}>{items.map(item => renderRow(item, rail))}</ul>
              </section>
            );
          })}
        </nav>
        <div className={styles.foot}>
          {settingsItem && <ul className={styles.list}>{renderRow(settingsItem, rail)}</ul>}
          {user && (
            <Popover>
              {rail ? <Tooltip content={user.name} side="right">{userTrigger(user)}</Tooltip> : userTrigger(user)}
              <PopoverContent side={rail ? "right" : "top"} align="start" className={styles.flyout}>
                {user.menu?.map(action => (
                  <PopoverClose asChild key={action.id}><button type="button" className={styles.flyoutRow} onClick={action.onSelect}>{action.label}</button></PopoverClose>
                ))}
              </PopoverContent>
            </Popover>
          )}
          {typeof footer === "function" ? footer({ rail }) : footer}
        </div>
      </div>
    );
  }

  const crumbs = found
    ? [...(found.section.title ? [{ label: found.section.title }] : []), ...found.trail.map(item => ({ label: item.label })), { label: found.item.label }]
    : [{ label: sections[0]?.title ?? header.name }];

  return (
    <div ref={setRoot} className={[styles.root, className].filter(Boolean).join(" ")} data-narrow={narrow ? "true" : undefined} data-frameless={frameless || undefined}>
      <div className={styles.status} role="status" aria-live="polite">{note}</div>
      {!narrow && (
        // Yuva yerleşimde yer tutar (şerit ya da açık); geçici açılan menü yuvadan taşar ve içeriğin üstüne çizilir.
        <motion.div className={styles.asideSlot} initial={false} animate={{ width: collapsed ? "3.5rem" : "16rem" }} transition={grow}>
          <motion.aside className={styles.aside} data-peek={peek ? "true" : undefined} initial={false} animate={{ width: collapsed && !peek ? "3.5rem" : "16rem" }} transition={grow}
            onMouseEnter={() => { inside.current.pointer = true; schedulePeek(true); }} onMouseLeave={() => { inside.current.pointer = false; schedulePeek(false); }}
            onFocus={() => { inside.current.focus = true; if (hoverExpand && collapsed) { window.clearTimeout(peekTimer.current); setPeek(true); } }}
            onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) { inside.current.focus = false; schedulePeek(false); } }}
            onKeyDown={event => { if (event.key === "Escape" && peek) setPeek(false); }}>
            {renderNav(collapsed && !peek)}
          </motion.aside>
        </motion.div>
      )}
      {!frameless && <div className={styles.main}>
        <header className={styles.topbar}>
          {narrow
            ? <Button variant="ghost" size="sm" aria-label="Menüyü aç" onClick={() => setDrawerOpen(true)}><Menu size={18} aria-hidden="true" /></Button>
            : <Tooltip content={collapsed ? "Menüyü genişlet" : "Menüyü daralt"}><Button variant="ghost" size="sm" aria-label={collapsed ? "Menüyü genişlet" : "Menüyü daralt"} aria-keyshortcuts="Control+B" onClick={() => setCollapsed(!collapsed)}><PanelLeft size={18} aria-hidden="true" /></Button></Tooltip>}
          <Breadcrumb items={crumbs} />
        </header>
        <div className={styles.content}>{children}</div>
      </div>}
      {narrow && (
        <Drawer open={drawerOpen} onOpenChange={setDrawerOpen}>
          <DrawerContent
            title={header.name} side="left" container={frameless ? undefined : root} className={styles.drawer}
            onOpenAutoFocus={event => {
              // Odak etkin satıra gider; yoksa ilk satıra.
              event.preventDefault();
              const panel = ((frameless ? null : root) ?? document).querySelector<HTMLElement>(`.${styles.drawer}`);
              (panel?.querySelector<HTMLElement>("[aria-current='page']") ?? panel?.querySelector<HTMLElement>("[data-nav-item]"))?.focus();
            }}
          >
            {renderNav(false)}
          </DrawerContent>
        </Drawer>
      )}
    </div>
  );
}

export default Sidebar;
